// Styles
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-dates/lib/css/_datepicker.css";

import React, { useState, useEffect } from "react";
import { useHistory } from "react-router-dom";
import { FormattedMessage } from "react-intl";
import { SingleDatePicker } from "react-dates";
import Loader from "react-loader-spinner";
import moment from "moment";
import Select from "react-select";

// Redux
import { connect } from "react-redux";
import { downloadInterAffReportGross, fetchInterAffiliateGrossSettlement } from "../../../../actions/filesets";
import { fetchAffiliatesNamesAndCodes, getRegionCodes } from "../../../../actions/affiliates";
import { closeAlert } from "../../../../actions/utils";

// Components
import { Alert, Button, Card, CardBody, CardHeader, Col, Row, Table as Table2 } from "reactstrap";
import ErrorMessage from "../../../../components/ErrorMessage";

// query string
const queryString = require("query-string");
const GrossSettlement = ({
	// function props
	closeAlert,
	getRegionCodes,
	downloadInterAffReportGross,
	fetchAffiliatesNamesAndCodes,
	fetchInterAffiliateGrossSettlement,
	// query string props
	location                           : { search: queryParams }, // gets the query string from props.search and save it as queryParams
	// state variables props
	alertError,
	download_status,
	regionCodes,
	allAffiliates,
	interAffiliateGrossSettlement,
	interAffiliateGrossSettlementError,
}) => {
	// QUERY STRING VARIABLES
	let { settlementDate } = queryString.parse(queryParams);
	let regionCode = queryString.parse(queryParams)["region-code"];
	let issuerCode = queryString.parse(queryParams)["issuer-code"];

	const history = useHistory(); // save react router history to history
	const [ focused, setFocused ] = useState(false);

	const [ startDate, setStartDate ] = useState(moment(settlementDate));
	useEffect(
		() => {
			setStartDate(moment(settlementDate));
		},
		[ settlementDate ],
	);

	// React select ony takes objec e.g {label: "USD": value:"USD"} so this construct achieves this but is also dynamic to what ever is passed as the region code in the query string.
	const [ selectedRegion, setSelectedRegion ] = useState({
		label : regionCode,
		value : regionCode,
	});
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setSelectedRegion({
				label : regionCode,
				value : regionCode,
			});
		},
		[ regionCode ],
	);

	// sets selectedIssuer state with the value of issuerCode gotten from the query string above
	const [ selectedIssuer, setselectedIssuer ] = useState({
		label : issuerCode,
		value : issuerCode,
	});

	// updates selectedIssuer as it changes in the questry string
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setselectedIssuer({
				label : issuerCode,
				value : issuerCode,
			});
		},
		[ issuerCode ],
	);

	// Use Effect Handles General Updates
	useEffect(
		() => {
			getRegionCodes();
			fetchAffiliatesNamesAndCodes();

			if (issuerCode === "ALL") {
				fetchInterAffiliateGrossSettlement(settlementDate, regionCode, issuerCode, "application/json");
			} else {
				fetchInterAffiliateGrossSettlement(settlementDate, regionCode, issuerCode, "");
			}
		},
		[ queryParams ],
	);

	const handleSubmitDate = (selectedDate, region, issuer) => {
		let settlementDate = moment(selectedDate).format("YYYY-MM-DD");
		history.push(
			`/interaffiliate/reports/gross-settlement?settlementDate=${settlementDate}&issuer-code=${issuer.value}&region-code=${region.label}`,
		);
	};

	let SelectRegion = [];
	SelectRegion =
		regionCodes &&
		regionCodes.map((region) => {
			return { label: region.code, value: region };
		});

	const onDismiss = () => closeAlert();

	return (
		<div className='animated fadeIn'>
			{alertError && (
				<Alert color='danger' isOpen={alertError} toggle={onDismiss}>
					{alertError ? alertError : "Error unable to download. Please Check you entries!"}
				</Alert>
			)}
			<Row>
				<Col lg={12}>
					<Card>
						<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
							<strong>
								<React.Fragment>
									<FormattedMessage id='Inter Affiliate ' defaultMessage='Inter Affiliate ' />
									{settlementDate}
									<FormattedMessage id=' Gross Settlement' defaultMessage=' Gross Settlement' />
								</React.Fragment>
							</strong>

							<div style={{ width: "73%" }} className={"d-flex justify-content-end align-items-center"}>
								<React.Fragment>
									<React.Fragment>
										<SingleDatePicker
											className={"mx-1"}
											showDefaultInputIcon={true}
											date={startDate} // momentPropTypes.momentObj or null
											onDateChange={(startDate) => setStartDate(startDate)} // PropTypes.func.isRequired
											focused={focused} // PropTypes.bool
											onFocusChange={({ focused }) => setFocused(focused)} // PropTypes.func.isRequired
											id='your_unique_id' // PropTypes.string.isRequired,
											isOutsideRange={() => false}
											numberOfMonths={1}
										/>
									</React.Fragment>
									<span style={{ width: "14%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setSelectedRegion(selectedOption)}
											value={selectedRegion}
											options={SelectRegion}
										/>
									</span>
									<span style={{ width: "18%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setselectedIssuer(selectedOption)}
											value={selectedIssuer}
											options={allAffiliates && allAffiliates}
										/>
									</span>
									<Button
										style={{
											padding                : "9px",
											borderTopLeftRadius    : "0px",
											borderBottomLeftRadius : "0px",
										}}
										className={"btn-sm mx-1"}
										onClick={() => handleSubmitDate(startDate, selectedRegion, selectedIssuer)}
										color='primary'
									>
										{" "}
										<FormattedMessage id='Submit' defaultMessage='Submit' />
									</Button>
								</React.Fragment>
								<React.Fragment>
									<Button
										className={"btn-sm ml-1"}
										style={{ padding: "8px" }}
										color='success'
										onClick={(e) =>
											downloadInterAffReportGross(settlementDate, regionCode, issuerCode)}
									>
										<span className={"d-flex px-2 justify-content-center align-items-center"}>
											<i className='fa fa-download' />&nbsp;
											{download_status ? (
												<Loader
													type='ThreeDots'
													color='#FFF'
													height={20}
													width={20}
													style={{ textAlign: "center" }}
												/>
											) : (
												<FormattedMessage id='Download CSV' defaultMessage='Download CSV' />
											)}
										</span>
									</Button>
								</React.Fragment>
							</div>
						</CardHeader>

						<CardBody>
							{/* Handle unselected fields */}
							{(regionCode === "Region" || issuerCode === "Issuer") &&
							!interAffiliateGrossSettlement &&
							interAffiliateGrossSettlementError && (
								<ErrorMessage
									message={
										"Please select your Region code and Issuer code and click Submit to view entries!"
									}
								/>
							)}

							{/* Handle Loading */}
							{regionCode !== "Region" &&
							issuerCode !== "Issuer" &&
							!interAffiliateGrossSettlementError &&
							!interAffiliateGrossSettlement && (
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							)}

							{/* Handle Errors */}
							{regionCode !== "Region" &&
							issuerCode !== "Issuer" &&
							!interAffiliateGrossSettlement &&
							interAffiliateGrossSettlementError &&
							interAffiliateGrossSettlementError.data && (
								<ErrorMessage message={interAffiliateGrossSettlementError.data.message} />
							)}

							{/* Handle Errors special cases */}
							{!interAffiliateGrossSettlement &&
							interAffiliateGrossSettlementError &&
							interAffiliateGrossSettlementError.data === "" && (
								<ErrorMessage message={"Error unable to load entries!"} />
							)}

							{/* Handle display content */}
							{interAffiliateGrossSettlement &&
							interAffiliateGrossSettlement.data && (
								<React.Fragment>
									{interAffiliateGrossSettlement.data.map((tableItem, index) => {
										return (
											<div id='accordion' key={index}>
												<div className='card'>
													<div className='card-header' id='headingOne'>
														<h5 className='mb-0'>
															<button
																className='btn'
																data-toggle='collapse'
																data-target={`#collapseOne${index}`}
																aria-expanded='true'
																aria-controls={`collapseOne${index}`}
															>
																<section
																	style={{ width: "110%" }}
																	className={
																		"d-flex justify-content-between align-items-center text-primary"
																	}
																>
																	<strong>{`${tableItem.issuer} `}</strong>

																	<span className='px - 2'>
																		{` Totals Count: ${tableItem.totalCount} `}
																	</span>
																	<span className='px - 2'>
																		{` Totals Amounts: ${tableItem.totalAmount} `}
																	</span>
																</section>
															</button>
														</h5>
													</div>

													<div
														id={`collapseOne${index}`}
														className='collapse'
														aria-labelledby='headingOne'
														data-parent='#accordion'
													>
														<div className='card-body'>
															<Table2 hover bordered striped responsive size='sm'>
																<thead>
																	<tr key={index}>
																		<th>{"Acquirer"}</th>
																		<th>{"Total Count"}</th>
																		<th>{"Total Amount"}</th>
																	</tr>
																</thead>
																<tbody>
																	{tableItem.acquirers.map((singleItem, index) => {
																		return (
																			<tr key={index}>
																				<td>{singleItem.left}</td>
																				<td>{singleItem.middle}</td>
																				<td>{singleItem.right}</td>
																			</tr>
																		);
																	})}
																	<tr>
																		<td>
																			<strong style={{ color: "blue" }}>
																				{"Total:"}
																			</strong>
																		</td>
																		<td>{tableItem.totalCount}</td>
																		<td>{tableItem.totalAmount}</td>
																	</tr>
																	{/* Important addition to separate each accordion */}
																	{null}
																	{null}
																</tbody>
															</Table2>
														</div>
													</div>
												</div>
											</div>
										);
									})}
								</React.Fragment>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		alertError                         : state.utils.alertError,
		download_status                    : state.fileSets.download_status,
		interAffiliateGrossSettlement      : state.fileSets.interAffiliateGrossSettlement,
		interAffiliateGrossSettlementError : state.fileSets.interAffiliateGrossSettlementError,
		regionCodes                        : state.affiliates.region_codes,
		allAffiliates                      : state.affiliates.affiliatesNamesAndCodes,
	};
};

export default connect(mapStateToProps, {
	closeAlert,
	fetchInterAffiliateGrossSettlement,
	downloadInterAffReportGross,
	fetchAffiliatesNamesAndCodes,
	getRegionCodes,
})(GrossSettlement);
